do.text:
dword pl;
float r;
float x;
float y;
pl = Player();
x = 1.0 * CoordX(pl);
y = 1.0 * CoordY(pl);
r = sqrt(x * x + y * y);
if (r < 1) {
  r = 1;
}
OrderMove(pl, round(x + x / r * 600.0), round(y + y / r * 600.0));
SFT('lab: start star=' + Name(ShipStar(pl)) + ' pos=' + CoordX(pl) + ',' + CoordY(pl) + ' inspace=' + ShipInNormalSpace(pl));
